import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int aWins = 0;
        int bWins = 0;
        for (int i = 0; i < n; i++) {
            String round = sc.next();
            if (round.length() != 2) {
                System.out.println("Invalid round");
                continue;
            }
            char c1 = round.charAt(0);
            char c2 = round.charAt(1);
            if ((c1 != 'R' && c1 != 'P' && c1 != 'S') || (c2 != 'R' && c2 != 'P' && c2 != 'S')) {
                System.out.println("Invalid round");
                continue;
            }
            switch (round) {
                case "RR":
                case "PP":
                case "SS":
                    System.out.println("Draw");
                    break;
                case "RS":
                case "PR":
                case "SP":
                    System.out.println("A");
                    aWins++;
                    break;
                case "RP":
                case "SR":
                case "PS":
                    System.out.println("B");
                    bWins++;
                    break;
            }
            if (aWins == 2 || bWins == 2) {
                break;
            }
        }
        if (aWins == 2) {
            System.out.println("A wins the match 2-" + bWins);
        } else if (bWins == 2) {
            System.out.println("B wins the match " + aWins + "-2");
        } else {
            System.out.println("Match drawn " + aWins + "-" + bWins);
        }
    }
}
